using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(string id);
    IReadOnlyList<Course> GetCourses(string? departmentId = null, string? search = null, int? credits = null);
    Course? GetCourse(string id);
    IReadOnlyList<Course> GetFeaturedCourses();
    void SubmitEnrollment(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = "math", Name = "Mathematics", Description = "Explore abstract structures, quantities, and patterns." },
            new() { Id = "eng", Name = "English", Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = "phys", Name = "Physics", Description = "Understand the fundamental laws governing the natural world." },
            new() { Id = "hist", Name = "History", Description = "Examine past events and their impact on the present." },
        ];

        _courses =
        [
            new()
            {
                Id = "cs101", Code = "CS 101", Title = "Introduction to Programming",
                Description = "Learn foundational programming concepts using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.",
                DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 3,
                Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201",
                Instructor = new() { Name = "Dr. Ada Lovelace", Title = "Associate Professor", Bio = "Dr. Lovelace has 15 years of experience teaching introductory CS courses and has published extensively on CS education.", Email = "alovelace@university.edu" },
                IsFeatured = true,
            },
            new()
            {
                Id = "cs301", Code = "CS 301", Title = "Data Structures & Algorithms",
                Description = "Study fundamental data structures (trees, graphs, hash tables) and algorithm design techniques including divide-and-conquer, dynamic programming, and greedy algorithms.",
                DepartmentId = "cs", DepartmentName = "Computer Science", Credits = 4,
                Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 305",
                Instructor = new() { Name = "Dr. Alan Turing", Title = "Professor", Bio = "Dr. Turing specializes in computational complexity theory and has received multiple teaching excellence awards.", Email = "aturing@university.edu" },
                IsFeatured = true,
            },
            new()
            {
                Id = "cs440", Code = "CS 440", Title = "Artificial Intelligence",
                Description = "Explore the principles and techniques of artificial intelligence, including search, knowledge representation, machine learning, and natural language processing.",
