    public IReadOnlyList<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetCourses(string? departmentId = null, string? search = null, int? credits = null)
    {
        IEnumerable<Course> query = _courses;

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        if (credits.HasValue)
            query = query.Where(c => c.Credits == credits.Value);

        return query.ToList();
    }

    public Course? GetCourse(string id) =>
        _courses.FirstOrDefault(c => c.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        // In a real app this would persist to a database.
        // For now, validation is handled by DataAnnotations on the model.
    }
}

arguments.file_text:
@code {
    [Parameter, EditorRequired]
    public required Course Course { get; set; }
}

.course-card {
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 1.25rem;
    background: #fff;
    transition: box-shadow 0.2s;
}

.course-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

.course-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.course-code {
    font-weight: 600;
    color: #1a56db;
    font-size: 0.875rem;
    text-transform: uppercase;
}

.course-credits {
    background: #e8f0fe;
    color: #1a56db;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 500;
}

.course-card h3 {
    margin: 0 0 0.4rem;
    font-size: 1.1rem;
}

.course-card h3 a {
    color: #1e293b;
    text-decoration: none;
}

.course-card h3 a:hover {
    color: #1a56db;
    text-decoration: underline;
}

.course-department {
    color: #64748b;
    font-size: 0.85rem;
    margin: 0 0 0.25rem;
}

.course-schedule {
    color: #64748b;
    font-size: 0.85rem;
    margin: 0;
}

@code {
    [Parameter] public string? Search { get; set; }
    [Parameter] public string? Department { get; set; }
    [Parameter] public int? Credits { get; set; }
    [Parameter, EditorRequired] public required IReadOnlyList<Department> Departments { get; set; }
}

.course-filters {
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1.5rem;
}

.filter-row {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    align-items: flex-end;
}

.filter-group {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    flex: 1;
    min-width: 160px;
}

.filter-group label {
    font-size: 0.85rem;
    font-weight: 600;
    color: #475569;
}

.filter-group input,
.filter-group select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    font-size: 0.9rem;
}

.filter-actions {
    flex-direction: row;
    align-items: flex-end;
    gap: 0.75rem;
    flex: 0;
}

.filter-actions button {
    padding: 0.5rem 1.25rem;
    background: #1a56db;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    white-space: nowrap;
}

.filter-actions button:hover {
    background: #1e40af;
}

.filter-actions a {
    color: #64748b;
    font-size: 0.875rem;
    white-space: nowrap;
}

@using UniversityCourseCatalog.Models

<div class="course-list">
    @if (Courses.Count == 0)
    {
        <p class="no-results">No courses match your criteria. Try adjusting the filters.</p>
    }
    else
    {
        <div class="course-grid">
            @foreach (var course in Courses)
            {
                <CourseCard Course="course" />
            }
        </div>
    }
</div>

