toolArgs.file_text:
@using UniversityCourseCatalog.Models

<div class="course-list">
    @if (Courses.Count == 0)
    {
        <p class="no-results">No courses match your criteria. Try adjusting the filters.</p>
    }
    else
    {
        <div class="course-grid">
            @foreach (var course in Courses)
            {
                <CourseCard Course="course" />
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public required IReadOnlyList<Course> Courses { get; set; }
}

.course-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 1.25rem;
}

.no-results {
    color: #64748b;
    font-style: italic;
    text-align: center;
    padding: 2rem;
}

