﻿@page "/"
@inject ICatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<section class="hero">
    <h1>University Course Catalog</h1>
    <p>Explore departments, discover courses, and enroll for the upcoming semester.</p>
    <div class="hero-actions">
        <a href="/courses" class="btn-primary">Browse Courses</a>
        <a href="/enroll" class="btn-secondary">Enroll Now</a>
    </div>
</section>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <CourseList Courses="featuredCourses" />
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="department-grid">
        @foreach (var dept in departments)
        {
            <a href="/courses?department=@dept.Id" class="department-link">
                <h3>@dept.Name</h3>
                <p>@dept.Description</p>
            </a>
        }
    </div>
</section>

@code {
    private IReadOnlyList<Course> featuredCourses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }
}

