arguments.file_text:
.hero {
    text-align: center;
    padding: 3rem 1rem;
    background: linear-gradient(135deg, #1e3a5f, #1a56db);
    color: #fff;
    border-radius: 12px;
    margin-bottom: 2.5rem;
}

.hero h1 {
    font-size: 2.25rem;
    margin: 0 0 0.75rem;
}

.hero p {
    font-size: 1.15rem;
    opacity: 0.9;
    margin: 0 0 1.5rem;
}

.hero-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
}

.btn-primary {
    background: #fff;
    color: #1a56db;
    padding: 0.65rem 1.5rem;
    border-radius: 6px;
    text-decoration: none;
    font-weight: 600;
}

.btn-secondary {
    border: 2px solid #fff;
    color: #fff;
    padding: 0.65rem 1.5rem;
    border-radius: 6px;
    text-decoration: none;
    font-weight: 600;
}

.featured-section,
.departments-section {
    margin-bottom: 2.5rem;
}

.featured-section h2,
.departments-section h2 {
    font-size: 1.5rem;
    margin: 0 0 1rem;
    color: #1e293b;
}

.department-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

.department-link {
    display: block;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 1.25rem;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s, border-color 0.2s;
}

.department-link:hover {
    border-color: #1a56db;
    box-shadow: 0 2px 8px rgba(26, 86, 219, 0.15);
}

.department-link h3 {
    margin: 0 0 0.4rem;
    color: #1a56db;
    font-size: 1.05rem;
}

.department-link p {
    margin: 0;
    color: #64748b;
    font-size: 0.875rem;
}

@page "/courses"
@inject ICatalogService Catalog

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1>Browse Courses</h1>

<CourseFilters Search="@Search"
              Department="@Department"
              Credits="@Credits"
              Departments="departments" />

<p class="results-count">@courses.Count course(s) found</p>

<CourseList Courses="courses" />

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }
    [SupplyParameterFromQuery] public int? Credits { get; set; }

    private IReadOnlyList<Course> courses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.GetCourses(Department, Search, Credits);
    }
}

.results-count {
    color: #64748b;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

.breadcrumb {
    font-size: 0.875rem;
    color: #64748b;
    margin-bottom: 1.5rem;
}

.breadcrumb a {
    color: #1a56db;
    text-decoration: none;
}

.breadcrumb a:hover {
    text-decoration: underline;
}

.course-detail header {
    margin-bottom: 1.5rem;
}

.course-detail .course-code {
    font-size: 0.9rem;
    font-weight: 600;
    color: #1a56db;
    text-transform: uppercase;
}

.course-detail h1 {
    margin: 0.25rem 0 0;
    font-size: 1.75rem;
    color: #1e293b;
}

.detail-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1rem;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1.5rem;
}

.detail-item {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

.detail-label {
    font-size: 0.8rem;
    font-weight: 600;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}

.course-description {
    margin-bottom: 1.5rem;
}

.course-description h2 {
    font-size: 1.2rem;
    margin: 0 0 0.5rem;
    color: #1e293b;
}

.enroll-cta {
    margin-top: 2rem;
    text-align: center;
}

.enroll-cta a {
    display: inline-block;
    background: #1a56db;
    color: #fff;
    padding: 0.75rem 2rem;
    border-radius: 6px;
    text-decoration: none;
    font-weight: 600;
    font-size: 1rem;
}

.enroll-cta a:hover {
    background: #1e40af;
}

@page "/enroll"
@inject ICatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>✅ Request Submitted</h2>
        <p>Your enrollment request has been received. You will be notified by email once it is processed.</p>
        <a href="/courses">Browse more courses</a>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment" method="post">
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="form-group">
            <label for="fullName">Full Name</label>
            <InputText id="fullName" @bind-Value="model.FullName" />
            <ValidationMessage For="() => model.FullName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="model.StudentId" />
            <ValidationMessage For="() => model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="model.CourseId">
                <option value="">— Select a course —</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.CourseId" />
        </div>

        <button type="submit" class="submit-button">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private IReadOnlyList<Course> courses = [];
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (!string.IsNullOrEmpty(CourseId) && string.IsNullOrEmpty(model.CourseId))
        {
            model.CourseId = CourseId;
        }
    }

    private void HandleSubmit()
    {
        Catalog.SubmitEnrollment(model);
        submitted = true;
    }
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
    color: #1e293b;
    font-size: 0.95rem;
}

.form-group input,
.form-group select {
    width: 100%;
    max-width: 480px;
    padding: 0.55rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group .validation-message {
    color: #dc2626;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.submit-button {
    background: #1a56db;
    color: #fff;
    padding: 0.65rem 1.75rem;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    margin-top: 0.5rem;
}

.submit-button:hover {
    background: #1e40af;
}

.success-message {
    background: #f0fdf4;
    border: 1px solid #86efac;
    border-radius: 8px;
    padding: 2rem;
    text-align: center;
}

