}

.course-detail h1 {
    margin: 0.25rem 0 0;
    font-size: 1.75rem;
    color: #1e293b;
}

.detail-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1rem;
