    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group .validation-message {
    color: #dc2626;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.submit-button {
    background: #1a56db;
    color: #fff;
    padding: 0.65rem 1.75rem;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    margin-top: 0.5rem;
}

.submit-button:hover {
    background: #1e40af;
}

.success-message {
    background: #f0fdf4;
    border: 1px solid #86efac;
    border-radius: 8px;
    padding: 2rem;
    text-align: center;
}

.success-message h2 {
    color: #166534;
    margin: 0 0 0.5rem;
}

.success-message p {
    color: #15803d;
    margin: 0 0 1rem;
}

.success-message a {
    color: #1a56db;
}

