toolArgs.file_text:
@page "/courses"
@inject ICatalogService Catalog

<PageTitle>Browse Courses — University Course Catalog</PageTitle>

<h1>Browse Courses</h1>

<CourseFilters Search="@Search"
              Department="@Department"
              Credits="@Credits"
              Departments="departments" />

<p class="results-count">@courses.Count course(s) found</p>

<CourseList Courses="courses" />

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public string? Department { get; set; }
    [SupplyParameterFromQuery] public int? Credits { get; set; }

    private IReadOnlyList<Course> courses = [];
    private IReadOnlyList<Department> departments = [];

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.GetCourses(Department, Search, Credits);
    }
}

.results-count {
    color: #64748b;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

