toolArgs.file_text:
@page "/enroll"
@inject ICatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="success-message">
        <h2>✅ Request Submitted</h2>
        <p>Your enrollment request has been received. You will be notified by email once it is processed.</p>
        <a href="/courses">Browse more courses</a>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment" method="post">
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="form-group">
            <label for="fullName">Full Name</label>
            <InputText id="fullName" @bind-Value="model.FullName" />
            <ValidationMessage For="() => model.FullName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="model.StudentId" />
            <ValidationMessage For="() => model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="model.CourseId">
                <option value="">— Select a course —</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => model.CourseId" />
        </div>

        <button type="submit" class="submit-button">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery]
    public string? CourseId { get; set; }

    private IReadOnlyList<Course> courses = [];
    private bool submitted;

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();

        if (!string.IsNullOrEmpty(CourseId) && string.IsNullOrEmpty(model.CourseId))
        {
            model.CourseId = CourseId;
        }
    }

    private void HandleSubmit()
    {
        Catalog.SubmitEnrollment(model);
        submitted = true;
    }
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
    color: #1e293b;
    font-size: 0.95rem;
}

.form-group input,
.form-group select {
    width: 100%;
    max-width: 480px;
    padding: 0.55rem 0.75rem;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    font-size: 0.95rem;
    box-sizing: border-box;
}

.form-group .validation-message {
    color: #dc2626;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.submit-button {
    background: #1a56db;
    color: #fff;
    padding: 0.65rem 1.75rem;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    margin-top: 0.5rem;
}

.submit-button:hover {
    background: #1e40af;
}

.success-message {
    background: #f0fdf4;
    border: 1px solid #86efac;
    border-radius: 8px;
    padding: 2rem;
    text-align: center;
}

.success-message h2 {
    color: #166534;
    margin: 0 0 0.5rem;
}

.success-message p {
    color: #15803d;
    margin: 0 0 1rem;
}

.success-message a {
    color: #1a56db;
}

